def main():
    rows = NEW[:100]
    assert len(rows) == 100
    path = Path(__file__).resolve().parent.parent / "data" / "pcos_qa.csv"
    with path.open("a", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        for row in rows:
            w.writerow(row)
    print("Appended", len(rows), "rows to", path)


if __name__ == "__main__":
    main()
